import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Gemini 排除项怎么写才生效","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-negative-tokens.md","filePath":"tools/gemini-negative-tokens.md","lastUpdated":1786871523000}'),i={name:"tools/gemini-negative-tokens.md"};function s(c,e,d,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="gemini-排除项怎么写才生效" tabindex="-1">Gemini 排除项怎么写才生效 <a class="header-anchor" href="#gemini-排除项怎么写才生效" aria-label="Permalink to &quot;Gemini 排除项怎么写才生效&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经官方文档逐一核实；文中「识别率」为 Gemini 给出的经验估算值，非官方测试数据，仅供相对参考。</li></ul></div><blockquote><p>提问：<code>no text / no logo / no camera cut / no morphing</code> 这类排除项，Gemini 和 Veo 实际认哪些？有没有一个「最有效排除项清单 + 推荐书写顺序」？</p></blockquote><h2 id="核心逻辑" tabindex="-1">核心逻辑 <a class="header-anchor" href="#核心逻辑" aria-label="Permalink to &quot;核心逻辑&quot;">​</a></h2><p>在 Gemini 和 Veo 的指令遵循体系中，单纯写「否定句」（如 <code>no X</code>）有时会触发模型的「粉象效应」——提到什么词，模型注意力就聚焦到该概念的潜在空间。</p><p>要让排除项绝对生效，Veo 最认同的方式是：「<strong>正向封闭式定义（Positive Anchoring）+ 行业级负向过滤词（Standardized Negative Tokens）</strong>」结合。</p><h2 id="一、gemini-veo-实际识别效果分级" tabindex="-1">一、Gemini &amp; Veo 实际识别效果分级 <a class="header-anchor" href="#一、gemini-veo-实际识别效果分级" aria-label="Permalink to &quot;一、Gemini &amp; Veo 实际识别效果分级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>排除项类型</th><th>原始否定写法</th><th>Veo 实际识别率</th><th>最佳生效写法（正反双重锁定）</th></tr></thead><tbody><tr><td>禁止分镜切换</td><td><code>no camera cut</code></td><td>95%</td><td><code>single continuous uncut shot</code>, <code>continuous single take</code>, <code>no jump cuts</code>, <code>uninterrupted camera movement</code></td></tr><tr><td>禁止文字 / Logo</td><td><code>no text, no logo</code></td><td>90%</td><td><code>clean unbranded surface</code>, <code>blank solid packaging</code>, <code>pristine studio plate</code>, <code>no typography</code>, <code>no text</code>, <code>no watermarks</code>, <code>no labels</code></td></tr><tr><td>禁止形变融化</td><td><code>no morphing</code></td><td>85%</td><td><code>rigid solid geometry</code>, <code>structural stability preserved</code>, <code>no warping</code>, <code>no melting</code>, <code>no rubbery deformation</code></td></tr><tr><td>禁止假材质 / 塑料感</td><td><code>not fake, no CGI</code></td><td>80%</td><td><code>authentic organic texture</code>, <code>natural microscopic flaws</code>, <code>no synthetic plastic look</code>, <code>no artificial gloss</code></td></tr><tr><td>泛化无效词（避坑）</td><td><code>no bad quality, no blur, not ugly</code></td><td>&lt; 10%（几乎无效）</td><td>直接用具体参数替代（如 <code>8k macro photography</code>, <code>sharp crisp focus</code>, <code>cinematic rim lighting</code>）</td></tr></tbody></table><h2 id="二、最有效排除项清单-按功能模块分类" tabindex="-1">二、最有效排除项清单（按功能模块分类） <a class="header-anchor" href="#二、最有效排除项清单-按功能模块分类" aria-label="Permalink to &quot;二、最有效排除项清单（按功能模块分类）&quot;">​</a></h2><p><strong>1. 镜头连贯与防切镜（Temporal &amp; Shot Stability）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>single continuous uncut shot, single take, locked temporal consistency, uninterrupted sequence, no camera cuts, no scene transitions, no jump cuts</span></span></code></pre></div><p><strong>2. 画面纯净度与去文字（Text &amp; UI Cleanliness）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clean unbranded plate, blank surface, minimal pristine background, no text, no logos, no typography, no watermarks, no subtitles, no UI overlays</span></span></code></pre></div><p><strong>3. 几何结构与防扭曲（Anti-Deformation / Anti-Morphing）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rigid solid body, preserved physical geometry, stable object contour, no warping, no melting, no morphing, no rubbery deformation, no flickering artifacts</span></span></code></pre></div><p><strong>4. 食品与材质真实感（Organic Material Authenticity）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authentic natural food texture, subtle micro-imperfections, controlled specular highlights, no synthetic plastic look, no artificial CGI gloss, no wax-like surface</span></span></code></pre></div><h2 id="三、黄金书写顺序与-prompt-结构模版" tabindex="-1">三、黄金书写顺序与 Prompt 结构模版 <a class="header-anchor" href="#三、黄金书写顺序与-prompt-结构模版" aria-label="Permalink to &quot;三、黄金书写顺序与 Prompt 结构模版&quot;">​</a></h2><p>为了保证权重清晰，不要把排除项散落在句子中间。推荐将 Prompt 划分为 4 层递进结构，把排除项统一收拢在最后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[第1层：正向主体与微观材质] → [第2层：机位运镜与参考系] → [第3层：主体动作与物理交互] → [第4层：标准排除与防崩约束块]</span></span></code></pre></div><p>实战 Prompt 范例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Subject &amp; Material] A single crispy golden French fry with delicate micro-blistered crust, subtle salt grains, and authentic food texture.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Camera &amp; Continuity] Single continuous uncut shot, a smooth slow dolly-in pushing forward along the z-axis.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Action &amp; Physics] The French fry falls vertically under realistic gravity onto a dark slate surface with a gentle bounce.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Negative Constraint Block] High-speed macro cinematography, 8k crisp focus, clean unbranded background, rigid solid geometry, preserved structural shape, no text, no logos, no watermarks, no camera cuts, no morphing, no warping, no synthetic plastic look.</span></span></code></pre></div><h2 id="四、核心规则与避坑要点" tabindex="-1">四、核心规则与避坑要点 <a class="header-anchor" href="#四、核心规则与避坑要点" aria-label="Permalink to &quot;四、核心规则与避坑要点&quot;">​</a></h2><ol><li><strong>禁止在否定句中使用生僻或模糊词</strong>：不要写 <code>no strange floating things</code>，直接写 <code>no debris, clean dark background</code>。</li><li><strong>包装文字优先用「Blank / Unbranded」做正向定义</strong>：对包装做去字处理时，在主体描述阶段就加上 <code>blank unbranded packaging</code>，比单纯在结尾写 <code>no logo</code> 的成功率高出一倍以上。</li><li><strong>单镜头杜绝分段描述</strong>：若 Prompt 中出现 <code>first camera does A, then camera does B</code>，极易被模型误判为分镜头剪辑；始终使用 <code>during the entire continuous shot</code> 维持单镜头状态。</li></ol><hr><p>关联：本文 <code>no text / no logo</code> 与 <a href="/tools/gemini-packaging-logo">包装文字不崩</a> 的「净版生成」是同一思路的正反两面（那篇用正向定义，本篇给标准写法）；<code>no camera cut</code> 与 <a href="/tools/gemini-camera-movement">机位与运镜</a> 的单镜连续性配合使用。</p>`,26)])])}const u=t(i,[["render",s]]);export{h as __pageData,u as default};
